  print('CHARTE MENTION',a['number'],len(a['source_xml']),a['source_id'])
for file,nums in [('travail.json',['L6332-7']),('impots.json',['260','260 A','286'])]:
 s=json.loads((root/file).read_text())
 for n in nums:
  matches=[a for a in s if a['number']==n]
  print('\\n',file,n,'matches',len(matches))
  for a in matches:
   print('state',a['source_state'])
   if n=='286':
    pars=re.findall(r'<p.*?</p>',a['source_xml'],re.S)
    print('\\n'.join(pars[:4]))
   else:print(a['source_xml'])
